    "title": "你的生命里，有没有一轮特意去追过的月亮？\\n \\n总在一些时刻，我们看到月亮。有人和朋友夜晚相聚，月亮西沉时，他们约好了下一次相见；有人和暗恋对象绕着操场一圈圈散步，抬头忽然撞见一轮巨大的明月，那个还没有问出口的问题，彼此都已经有了答案；还有人看到月亮，就想起逝去的奶奶，想起童年奶奶摇着蒲扇，给她讲嫦娥奔月的故事。\\n \\n也因此，有人奔赴山海，只为「追」到一轮心中的月亮。有人和朋友专程跑到马来西亚，在海边等来一轮真正的「海上升明月」，月亮又低、又大、又圆；有人特意去到沙漠，没有建筑物遮挡，月亮悬在地平线",
